(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lv"] = {"ui":{"skip":"Pāriet uz saturu","back":"← Atpakaļ uz AI-gile","lang.button":"Valoda: {name}","lang.dialog":"Izvēlies valodu","lang.search":"Meklēt valodas","lang.none":"Neviena valoda neatbilst","lang.notYet":"{name} vēl nav iztulkota","theme.aria":"Pārslēgt tēmu: gaiša, tumša vai melna","theme.toLight":"Pārslēgt uz gaišo tēmu","theme.toDark":"Pārslēgt uz tumšo tēmu","theme.toBlack":"Pārslēgt uz melno tēmu (īsti melna, saudzīga OLED ekrāniem)","words.underline":"Pasvītrot šos vārdus lapā","words.underlineHelp":"Novieto kursoru uz vārda ar punktētu pasvītrojumu vai pieskaries tam, lai redzētu, ko tas nozīmē.","index.title":"AI-gile: tava MI izstrādes komanda vienā tāfelē","index.description":"AI-gile ir kanban tāfele MI programmēšanas komandām. Tās strādā, kamēr tu guli; tev paliek viena īsa kaudzīte: ko izlemt, ko pārbaudīt un ko pieņemt.","hero.logoAlt":"AI-gile tāfeles ikona","hero.h1.html":"Tava MI izstrādes komanda vienā&nbsp;tāfelē.","hero.alpha":"🐣 Slēgta pirmsalfa","hero.alphaTitle":"Agrīna un nepabeigta: paldies, ka izmēģini!","hero.lede":"Viņi būvē, kamēr tu guli. Pamodies tu atrodi vienu īsu kaudzīti: pāris jautājumu, pāris lietu, ko pārbaudīt, un viens otrs violets dimants. Uzklikšķini, pieņem un atpakaļ pie kafijas.","dl.windows":"Windows lietotne","dl.browser":"Palaid pārlūkā","dl.messenger":"📱 Messenger tavam telefonam","dl.soon":"Drīzumā","dl.notify":"🔔 Pastāsti, kad atvērsies","dl.notifySmall":"Alfa vai beta","hero.secondary":"Agile, bet komandai nekad nevajag stāvošo rīta kafiju. (Stand-up viņi tāpat rīko.)","pitch.h2":"AI-gile tik vārdos, cik vēlies","pitch.lede":"Izvēlies garumu, no viena vārda līdz 144. Katrs garums ir savs apraksts, uzrakstīts tieši tam. Velc slīdni vai lieto bulttaustiņus.","pitch.rangeLabel":"Garums vārdos","pitch.dice":"🎲 cita versija","pitch.words.one":"{n} vārds","pitch.words.other":"{n} vārdi","pitch.letters.one":"{n} burts","pitch.letters.other":"{n} burti","pitch.chars.one":"{n} rakstzīme","pitch.chars.other":"{n} rakstzīmes","count.line.html.one":"Tāfelē šobrīd ir {n} kartīte","count.line.html.other":"Tāfelē šobrīd ir {n} kartītes","people.humans.html.one":"👥 {n} cilvēks","people.humans.html.other":"👥 {n} cilvēki","people.agents.html.one":"🤖 {n} aģents","people.agents.html.other":"🤖 {n} aģenti","people.working.html.one":"⚡ {n} šobrīd strādā","people.working.html.other":"⚡ {n} šobrīd strādā","pre.title":"AI-gile: šeit kaut kas top","pre.description":"Šeit kaut kas top: tāfele, kurā MI komandas būvē to, ko tu palūdz, un pa ceļam tevi māca. Pagaidām slēgta pirmsalfa ar draugiem.","pre.h1":"Šeit kaut kas top. 🤫","pre.line":"Tāfele, kurā MI komandas būvē to, ko tu palūdz, un pa ceļam tevi māca. Pagaidām slēgta pirmsalfa ar draugiem.","pre.btn":"🔔 Pastāsti, kad atvērsies","pre.peek":"Aiz stikla: īstā tāfele, tiešraidē. Katra kartīte ir krāsaina svītra.","pre.peekFake":"Aiz stikla: tā izskatās tāfele darbā.","features.aria":"Ko tā dara","f.pile.h":"Viena kaudzīte tev","f.pile.html":"<b>Tev</b> satur visu, kas gaida tevi, no visiem projektiem: jautājumus, lietas, ko pārbaudīt, un uzdevumus, ko var izdarīt tikai cilvēks. Tava rinda parāda, kas ir nākamais un cik tas aizņems.","f.sleep.h":"Komandas, kas strādā, kamēr tu guli","f.sleep.p":"Katram projektam ir līderis un MI aģentu komanda. Komentē kartīti, un komanda pamostas, paveic darbu un atdod to atpakaļ ar soļiem, kurus var izpildīt arī nogurusi cilvēks.","f.tester.h":"Vispirms pārbauda MI testētājs","f.tester.p":"Pirms kaut kas nonāk pie tevis, testētājs izpilda soļus lietotnes kopijā un parāda redzēto ar ekrānuzņēmumu. Pārlapo izturējušos un pieņem ar vienu klikšķi.","f.proof.h":"Pierādījumi, nevis solījumi","f.proof.p":"Katra nodošana parāda, kas mainījies: failus, atšķirības, ekrānuzņēmumus. Nav jāatver katra lietotne, lai redzētu, vai viss gatavs.","f.chat.h":"Tērzē ar saviem līderiem","f.chat.p":"Discord stila josla: viena ikona katram projektam, violeti dimanti tam, kam vajag tevi. Uzraksti līderim ideju; viņš to pārvērš kartītēs un plānā ar pogu ✅ Aiziet.","f.tidy.h":"Pati uztur kārtību","f.tidy.p":"Saistītās kartītes saplūst vienā, juceklīgi nosaukumi tiek sakārtoti, un tokenu pārbaude uztur kodu kompaktu. Mazāk, starp ko pārslēgties, mazāk, par ko domāt.","f.private.h":"Tava, tavā datorā","f.private.li1":"Tāfele darbojas tavā paša datorā un atbild tikai tev.","f.private.li2":"Privātās ziņas starp cilvēkiem ir šifrētas no gala līdz galam.","f.private.li3":"Nekādu kontu, izsekotāju un sīkdatņu.","f.lang.h":"Tavā valodā","f.lang.p":"Vairāk nekā 120 valodu, no holandiešu, velsiešu un japāņu līdz pirātu, Jodas un klingonu valodai, ar ātru pārslēgšanos atpakaļ uz angļu valodu nozares žargonam.","f.service.h":"No idejas līdz īstam pakalpojumam","f.service.p":"Ar MI uzbūvēji kaut ko, ko cilvēki tagad lieto? Atzīmē to kā pakalpojumu, un dēlis palīdz to labi uzturēt: pieejamības pārbaudes, publiska statusa lapa, incidenti ar pēcanalīzi, izmaiņas, kurām vajag Go, dublējumi, ko pārbauda katru dienu. Palīdzība māca katru soli pa ceļam.","msgr.h2":"AI-gile Messenger: tava komanda kabatā","msgr.p1":"Runā ar savu MI komandu, neatverot dēli. Tērzē ar projektu vadītājiem un draugiem, skaties kartītes testa soļus un atbildi uz tiem, viss no tava telefona.","msgr.p2":"Lai savienotu pārī, noskenē QR kodu savā dēlī. Pirmā reize? Draudzīga demo tērzēšana visu parādīs.","msgr.when":"Vispirms Android, pēc tam tīmekļa versija telefoniem un iPhone.","msgr.who":"Tavs projekta vadītājs","msgr.b1":"Tumšā režīma labojums ir gatavs. Atsūtīt testa soļus?","msgr.b2":"Jā, lūdzu!","msgr.b3":"1. Atver Iestatījumus. 2. Izvēlies Tumšo. Vai izskatās pareizi?","tl.aria":"Laika līnija no pirmās sarunas līdz ceļvedim","tl.h2":"No pirmās sarunas līdz tam, kas sekos","tl.lede":"Īsti datumi un laiki tavā laika joslā. Pēc šodienas tas ir plāns, bez solītiem datumiem.","tl.today":"Šodien","tl.planned":"plānots","tl.doing":"procesā","tl.cards.one":"{n} kartīte","tl.cards.other":"{n} kartītes","join.h2":"Pievienojies","join.lede":"AI-gile veido bārdains dīvainis ar AuDHD un dažām cīņām ar mentālo veselību, un liels pulks pacietīgu aģentu. Pagaidām tā ir privāta, slēgtā alfā kopā ar draugiem. Vai gribi izmēģināt, kad tā atvērsies?","join.btn":"Pieteikt interesi","join.small":"Mēs uzrakstīsim e-pastu un neko citu","footer.tag":"AI-gile. Nekādu izsekotāju, nekādu sīkdatņu, nekādas stāvošās rīta kafijas.","footer.licence":"Biznesa licence","footer.status":"Statuss","footer.privacy":"Ko mēs glabājam","footer.thanks":"Zvani, pateicoties ChilledChat","form.sending":"Sūta…","form.failed":"Neizdevās: mēģini vēlāk vēlreiz.","form.offline":"Neizdevās sazināties ar AI-gile: mēģini vēlāk vēlreiz.","form.keep":"Mēs to izmantojam tikai, lai tev atbildētu, un pēc tam izdzēšam. Nekādu izsekotāju, nekādu sīkdatņu.","form.keepLink":"Ko mēs glabājam","interest.title":"AI-gile: pastāsti, kad atvērsies alfa","interest.description":"Atstāj savu e-pastu, lai uzzinātu, kad atvērsies AI-gile slēgtā alfa vai beta.","interest.h1":"🔔 Pastāsti, kad atvērsies","interest.lede":"AI-gile ir slēgtā pirmsalfā. Atstāj e-pastu, un mēs uzrakstīsim vienreiz, kad tev būs vieta.","interest.email":"Tavs e-pasts","interest.which":"Kuru testu?","interest.alpha":"Slēgtā alfa: agrīna, raupja, daudz izmaiņu","interest.beta":"Beta: stabilāka, vēlāk","interest.both":"Jebkuru, kas būs pirmā","interest.submit":"Pieraksti mani sarakstā","interest.thanks":"Paldies! Tu esi sarakstā.","licence.title":"AI-gile: biznesa licence","licence.description":"Lieto AI-gile savā uzņēmumā? Pieprasi bezmaksas biznesa licenci.","licence.h1":"📜 Biznesa licence","licence.lede":"Lieto AI-gile darbā? Pastāsti, kas tu esi un ar ko nodarbojies. Ja tas nes kādu labumu, licence ir bez maksas.","licence.company":"Uzņēmums","licence.website":"Tīmekļa vietne","licence.what":"Ar ko nodarbojies","licence.how":"Kā tas palīdz pasaulei","licence.email":"E-pasts","licence.submit":"Pieteikties","licence.thanks":"Paldies! Atbildēsim pa e-pastu.","status.title":"AI-gile statuss","status.h1":"AI-gile statuss","status.quiet":"Viss mierīgi","status.intro":"Vai AI-gile šobrīd darbojas? Šī lapa ik pēc 5 minūtēm pārbauda vietni, tāfeļu koplietošanu, zvanus un lejupielādi.","status.up":"Darbojas (atbildēja {ms} ms laikā)","status.slow":"Neatbildēja uz pēdējo pārbaudi, mēģina vēlreiz","status.down":"Nedarbojas: neatbildēja uz pēdējām divām pārbaudēm","status.svc.web":"Vietne","status.svc.web.offers":"Šī vietne: kas ir AI-gile, un interešu pieteikuma veidlapa","status.svc.boards":"Tāfeļu koplietošana","status.svc.boards.offers":"Publiskas tāfeles, ziņas starp draugiem un ielūgumi","status.svc.calls":"Zvani","status.svc.calls.offers":"Balss, video un ekrāna kopīgošana AI-gile","status.svc.download":"Lejupielāde","status.svc.download.offers":"Windows instalētājs un ielūgumu saites","status.checking":"Pārbauda…","status.offline":"Šobrīd nevar sazināties ar statusa pakalpojumu (mēģina vēlreiz)","status.updated":"atjaunināts {ago}","status.justNow":"tikko","status.min":"pirms {n} min","status.hours":"pirms {n} h","status.days":"pirms {n} d","privacy.title":"AI-gile: ko mēs glabājam","privacy.h1":"Ko mēs glabājam","privacy.lede":"Īsumā: tikai to, ko tu mums nosūti, un ne ilgi.","privacy.only":"Tikai to, ko tu mums nosūti: to, ko ieraksti veidlapā, piemēram, savu e-pastu. Neko citu par tevi.","privacy.sealed":"Tas tiek aizzīmogots, lai mūsu serveris to nevarētu izlasīt: jau tavā pārlūkā, pirms tas tiek nosūtīts (vecākā pārlūkā tajā brīdī, kad tas pienāk). Atvērt to var tikai mūsu pašu tāfele.","privacy.server":"No servera tas tiek izdzēsts, tiklīdz nonāk mūsu tāfelē. Viss, kas tur vēl ir pēc 30 dienām, tiek izdzēsts jebkurā gadījumā.","privacy.board":"Mūsu tāfelē mēs to glabājam tikai līdz brīdim, kad esam tev atbildējuši, un tad izdzēšam arī tur.","privacy.none":"Nekādu izsekotāju, nekādu sīkdatņu, nekādas analītikas.","privacy.local":"Tava valoda un gaišās vai tumšās tēmas izvēle paliek tavā pārlūkā. Tās nekad netiek sūtītas mums.","privacy.ask":"Gribi, lai to izdzēšam ātrāk? Atbildi uz mūsu e-pastu un pasaki to.","live.h2":"Skaties, kā tas top, tiešraidē","live.caption":"Katra kartīte ir paslēpta: tu redzi darba formu, nevis vārdus.","live.watching.one":"tiešraidē: {n} skatās","live.watching.other":"tiešraidē: {n} skatās","live.last.now":"Pēdējā kartīte pārvietota tikko","live.last.min.one":"Pēdējā kartīte pārvietota pirms {n} min.","live.last.min.other":"Pēdējā kartīte pārvietota pirms {n} min.","live.last.hour.one":"Pēdējā kartīte pārvietota pirms {n} st.","live.last.hour.other":"Pēdējā kartīte pārvietota pirms {n} st.","live.last.day.one":"Pēdējā kartīte pārvietota pirms {n} d.","live.last.day.other":"Pēdējā kartīte pārvietota pirms {n} d.","live.offline":"Tiešraides tāfele mazliet atpūšas. Ieskaties drīz vēlreiz.","live.cols":"Backlogs|Darāmais|Procesā|Komanda pārbauda|Gaida tavu testu|Komandai|Izdarīts","pitch.words.zero":"{n} vārdu","pitch.letters.zero":"{n} burtu","pitch.chars.zero":"{n} rakstzīmju","count.line.html.zero":"Tāfelē šobrīd ir {n} kartīšu","tl.cards.zero":"{n} kartīšu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Deleģēts."]},{"n":2,"texts":["Robotu kanban.","Aģenti, sakārtoti.","Idejas, uzbūvētas."]},{"n":3,"texts":["Kanban robotiem.","Idejas kļūst funkcijās.","Bezmaksas aģentu kanban."]},{"n":5,"texts":["Kanban tāfele, ko vada aģenti.","Tu raksti kartītes. Aģenti būvē.","Bezmaksas, vietēja, pārbaudīta, mazliet jocīga."]},{"n":8,"texts":["Bezmaksas kanban tāfele, kur strādā MI aģenti.","Uzraksti ideju. Aģenti to uzbūvē. Tu to pieņem.","Agile vienam cilvēkam un daudziem pacietīgiem robotiem."]},{"n":13,"texts":["Kanban tāfele tavā datorā, kurā kartītes pa vienai paņem MI aģenti, kamēr tu atpūties.","Uzraksti ideju. To uzbūvē aģentu komanda. Pēc tam testētājs to rūpīgi pārbauda un parāda.","Bez kontiem, bez izsekotājiem: tāfele, daži roboti un tu, kas visu izlemj."]},{"n":21,"texts":["AI-gile ir kanban tāfele darbam ar MI programmēšanas aģentiem. Viņi paņem kartītes, bet tu tās pārbaudi un pieņem.","Katram projektam ir savs līderis un MI aģentu komanda. Komentē jebkuru kartīti, un komanda uzreiz ķeras pie darba.","Bezmaksas personīga darāmo lietu tāfele, kas darbojas tavā datorā. Darbinieki ir roboti. Tas, kurš saka jā, esi tu."]},{"n":34,"texts":["Tu liec idejas uz tāfeles. MI aģentu komanda pārvērš tās strādājošās funkcijās, pārbauda un atdod atpakaļ ar soļiem, kā izmēģināt. Nekas nav gatavs, kamēr tu to neesi pateicis.","AI-gile ir mājās darināta kanban tāfele, ko uzbūvēja Rich, lielā mērā ar to aģentu palīdzību, kurus tā tagad vada. Tā ir bezmaksas, darbojas tavā datorā un tiek dalīta ar draugiem, nevis pārdota.","Iedomājies parastu kanban tāfeli ar kolonnām no Backloga līdz Izdarītam, tikai kartītes paņem MI aģenti. Viņi ziņo par progresu, jautā, kad iestrēguši, un vienmēr gaida tavu īkšķi uz augšu."]},{"n":55,"texts":["AI-gile ir kanban tāfele, kurā komanda sastāv no MI aģentiem. Katram projektam ir līderis, kas plāno darbu, un palīgi, kas to būvē. Kad funkcija ir gatava, MI testētājs to izmēģina un uzņem ekrānuzņēmumu, tad tā nonāk tavā kaudzītē. Pieņem to vai komentē, un viņi darbu pārstrādā.","Tas sākās kā viena cilvēka veids, kā sekot daudzām MI programmēšanas sesijām vienlaikus, un izauga par īstu tāfeli. Tā darbojas tavā datorā, nevajag konta un nav izsekotāju. Tā ir bezmaksas draugiem un ikvienam ziņkārīgajam. Tā ir arī nepabeigta, tāpēc gaidi raupjas malas un reizēm kādu pārsteigumu.","Lūk, godīgā versija. Idejas tev joprojām jāizdomā, un rezultāti tev joprojām jāpārbauda. AI-gile dara visu pa vidu: tur kārtībā kartītes, pamodina īsto aģentu, kad tu komentē, parāda, kas tieši mainījies, un visu savāc vienā īsā kaudzītē, lai tev nav jāmeklē pa visiem projektiem un jāpārslēdzas starp lietotnēm."]},{"n":89,"texts":["AI-gile ir bezmaksas kanban tāfele, ko tu palaid savā datorā. Cilvēku vietā katram projektam ir sava MI aģentu komanda: līderis, kas tavas idejas pārvērš kartītēs un plānā, un palīgi, kas kartītes ķer pēc prioritātes. Kad kaut kas uzbūvēts, MI testētājs izpilda testa soļus un parāda, ko redzēja. Tad tas gaida vienā kaudzītē ar nosaukumu Tev. Tu to pieņem vai komentē, un komanda mēģina vēlreiz, ja vajag. Līdz Izdarīts nekas nenonāk bez tevis.","Dažas lietas, ko varbūt negaidi. Nakts sardze, kamēr tu guli, papildina kolonnu Darāmais ar kartītēm, kurām nevajag tavu atbildi. Tokenu skaitītājs rāda, cik aģenti šodien un šonedēļ iztērējuši, un režīms Bez tokeniem liek viņiem pārstāt tērēt. Tu vari rakstīt draugiem, un privātās ziņas ir šifrētas no gala līdz galam. Tāfele runā aptuveni 120 valodās, tostarp holandiešu, flāmu, pirātu un klingonu. Nekas no tā nemaksā ne santīma, un neviens arī necenšas tev to pārdot.","AI-gile ir neliels personīgs projekts, nevis uzņēmums. Rich gribēja pieskatīt vairākus MI programmēšanas projektus, neatverot katru lietotni, tāpēc viņš un aģenti uzbūvēja tāfeli, un tad ar to uzbūvēja pārējo pašu. Tā ir slēgtā pirmsalfā, kas nozīmē, ka lielākoties tā darbojas, bet to izmēģina tikai daži draugi. Neviens neko nepārdod, neviens nevāc tavus datus. Nav cenu lapas, nav jaunumu vēstuļu un nav izaugsmes plāna. Ja šķiet noderīgi, vari pieteikties izmēģināt, kad tā atvērsies nedaudz plašāk."]},{"n":144,"texts":["AI-gile ir kanban tāfele vienam cilvēkam un daudziem MI aģentiem. Tā darbojas tavā paša datorā un ir pilnīgi bezmaksas. Tu pievieno projektus, un katram projektam ir līderis un neliela komanda. Tu tērzē ar līderi, mazliet kā Discord, un apraksti ideju; līderis to pārvērš kartītēs un plānā, un tad gaida, kad nospiedīsi Aiziet. Komanda kartītes izstrādā pēc prioritātes, izmantojot vienkāršu komandrindu, kas radīta valodas modeļiem. Pirms kaut kas atgriežas pie tevis, MI testētājs izpilda soļus lietotnes kopijā un pievieno ekrānuzņēmumu. Pabeigtais darbs nonāk tavā kaudzītē kopā ar mainītajiem failiem un atšķirībām. Tu to pieņem vai atstāj komentāru, un komanda pamostas un mēģina vēlreiz. Tāfele sevi arī uzkopj: saistītās kartītes tiek apvienotas, un juceklīgi nosaukumi sakārtoti. Kartīti uz Izdarīts var pārvietot tikai tu. Neviens cits to nevar, pat visizcilākais aģents ne.","Aptuveni tāda ir diena ar AI-gile. Vakarā tu atstāj dažus komentārus: šī poga ir nepareizā vietā, šis saraksts jākārto, vai varētu būt tumšais režīms. Tu ej gulēt. Aģenti izlasa komentārus, veic izmaiņas, pārbauda tās un atdod tev atpakaļ. Ja Darāmais izsīkst, nakts sardze to papildina no backloga ar kartītēm, kurām nevajag tavu atbildi. Rītā ir viena īsa kaudzīte: pāris jautājumu un dažas lietas, ko izmēģināt, katrai ar soļiem, ko var izpildīt miegains cilvēks, un ekrānuzņēmumu, kā tas strādā. Tu pārklikšķini, pieņem labās un atsūti atpakaļ pārējās. Ja kaut kas nav skaidrs, tu vienkārši komentē, un tas atkal nonāk pie komandas. Tokenu skaitītājs rāda, cik tas viss patērēja, un režīms Bez tokeniem ir tievām nedēļām. Tad tu brokasto, kam aģenti vēl nevar palīdzēt.","Vispirms, kas AI-gile nav. Tas nav jaunuzņēmums, tas netiek pārdots, un neviens nevāc tavus datus. Tā ir bezmaksas tāfele, kas darbojas tavā datorā, bez kontiem, bez izsekotājiem un bez sīkdatnēm. Kas tā ir: viena kārtīga vieta, kur uzreiz redzēt visus MI programmēšanas projektus, kur kartītes dara aģentu komanda, bet lēmumus pieņem tu. Tajā ir arī nakts sardze, kas kartītes sagatavo, kamēr tu guli. Tā apvieno saistītās kartītes, sakārto juceklīgus nosaukumus un pieskata, cik kompakts paliek kods. Tā runā aptuveni 120 valodās, no holandiešu un flāmu līdz pirātu un klingonu. Draugi var sūtīt viens otram ziņas, privāti un šifrēti. To uzbūvēja Rich un liels pulks pacietīgu aģentu, galvenokārt izmantojot pašu tāfeli. Tā ir slēgtā pirmsalfā, tāpēc dažviet vēl ir raupja. Ja šķiet jautri, pieklājīgi pajautā, un varbūt tiksi iekšā agrāk."]}],"quips":{"1":"Viens vārds. Drosmīgi. Varbūt pat pārāk drosmīgi.","3":"Trīs vārdi. Jau godīgāk nekā vairums produktu lapu.","8":"Astoņi vārdi. Joprojām īsāk par stand-up.","21":"Garumi, starp citu, ir stāstu punkti. Protams, ka ir.","55":"Piecdesmit pieci vārdi. Kamēr tu to lasīji, divas kartītes tika pabeigtas.","144":"Tas ir garais. 233 nav. Aģenti ir aizgājuši gulēt."}},"timeline":{"first-idea.name":"Pirmā ideja","first-idea.line":"Pati pirmā saruna, pirms vēl bija kāds kods.","first-board.name":"Pirmā tāfele","first-board.line":"Tāfele, kas seko savai būvei: kartītes, kolonnas, vilkšana, projekti.","team-roles.name":"Komanda un lomas","team-roles.line":"Aģentu profili, komandu veidnes, telpas un kurš ko dara.","install.name":"Uzstādīšana un laidieni","install.line":"Zip, ko draugs var uzstādīt, pašatjaunināšanās, kanāli un atgriešanās.","usage-saver.name":"Patēriņa taupītājs","usage-saver.line":"Mēra, cik izmaksā darbs, uztur kodu kompaktu, taupa tavu limitu.","friends.name":"Draugi un kopīgošana","friends.line":"Privātas ziņas, sajaukts releja kanāls, ielūgumi, lomas un kopīgi projekti.","languages.name":"Valodas","languages.line":"Katrs ekrāna teksts valodas failā, vispirms holandiešu un flāmu valoda.","ai-tester.name":"MI testētājs","ai-tester.line":"Testētājs vispirms pārbauda katru nodošanu un parāda redzēto.","website.name":"Mājaslapa","website.line":"aigile.lol, ievada lapa un šī laika līnija.","streaming.name":"Tērzēšana un straumēšana","streaming.line":"Discord, Twitch, OBS, straumētāja režīms, GIF un emocijzīmes.","no-ai.name":"Izdevums bez MI","no-ai.line":"Tāfele cilvēkiem, kas programmē bez MI, un publiskas tāfeles.","night-watch.name":"Nakts sardze","night-watch.line":"Sargs un Scrum Master notur komandas pie darba, kamēr tu guli.","p-more.name":"Viss pārējais","p-more.line":"Mazākas idejas, kas vēl gaida savu kārtu.","p-android.name":"Telefons un Android","p-android.line":"Piekļuve tāfelei no telefona, pēc tam dabiska Android lietotne.","p-release.name":"Alfa un tālāk","p-release.line":"Slēgtā alfa, dzīvā vietne, tad beta.","p-languages.name":"Vairāk valodu","p-languages.line":"130 valodas un iegremdēšanās režīms tiem, kas mācās.","p-engines.name":"Vairāk MI dzinēju","p-engines.line":"Katram aģentam izvēlies Claude, Codex, Gemini, Copilot vai Cursor.","p-pro.name":"Profesionāla prakse","p-pro.line":"Riska atzīmes, sapludināšanas vārti, incidentu kartītes un aizsargbarjeras.","p-self.name":"Rūpes par tevi","p-self.line":"Noguruma režīms, atgādinājumi par sevis kopšanu un 4:20.","p-servers.name":"Serveri un mērogs","p-servers.line":"Globāli servera iestatījumi, lomas un plānošana izaugsmei.","p-livestream.name":"Straumēšanas papildinājumi","p-livestream.line":"Twitch tērzētava, pašu emocijzīmes un publisks tiešraides skats."},"words":{"button":"📖 Nozares žargons","h":"📖 Vārdi paskaidroti","intro":"Vārdi, ko sastopi AI-gile, vienkāršā valodā: kā to būvēt, kā to droši mainīt, kā uzturēt to darbībā cilvēkiem, kas to lieto, un kā strādāt komandā ar MI.","search":"Meklēt vārdu…","none":"Neviens vārds neatbilst.","close":"Aizvērt","count":{"one":"{count} vārds","other":"{count} vārdi"},"groups":[{"id":"build","name":"🛠️ Būvēšana"},{"id":"change","name":"🔀 Droša mainīšana"},{"id":"run","name":"🛎️ Pakalpojuma uzturēšana"},{"id":"team","name":"🤝 Darbs komandā (un ar MI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Projekta koda mape un tās pilnā commit vēsture, parasti glabāta arī GitHub.","also":["repozitorijs","repozitorija"]},{"id":"branch","g":"build","word":"Branch","text":"Atsevišķa darba līnija kodā, lai izmaiņas varētu veikt, neskarot galveno versiju.","also":["branches","zars","zara","zari"]},{"id":"commit","g":"build","word":"Commit","text":"Saglabāts koda momentuzņēmums ar īsu piezīmi par to, kas mainījās. Vienmēr var atgriezties pie kāda no tiem.","also":["commits","commiti","commita","commitu"]},{"id":"push","g":"build","word":"Push","text":"Saglabāto momentuzņēmumu (commit) sūtīšana no šī datora uz GitHub, lai tie būtu dublēti un kopīgoti."},{"id":"merge","g":"build","word":"Merge","text":"Zara izmaiņu apvienošana atpakaļ galvenajā versijā."},{"id":"pr","g":"build","word":"Pull request","text":"Lūgums pārbaudīt zara izmaiņas un apvienot tās galvenajā versijā.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktorēšana","text":"Koda sakārtošana, nemainot to, ko tas dara: mazāki faili, skaidrāki nosaukumi, mazāk atkārtojumu."},{"id":"bug","g":"build","word":"Kļūda","text":"Kaut kas, kas nedarbojas tā, kā vajadzētu.","also":["kļūdas","kļūdu","kļūdai","kļūdām","bugs","bugi","buga"]},{"id":"test","g":"build","word":"Tests","text":"Pabeigta darba izmēģināšana, lai pārbaudītu, vai tas dara to, kas prasīts, pirms to pieņem.","also":["testi","testa","testu","testam","testēt","testēšanai","testēšana","testējami","testējams","jātestē"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Saīsinājums no angļu quality assurance (kvalitātes nodrošināšana): automātiskās pārbaudes, kas notiek, pirms kaut kas nonāk darbībā. Ja QA ir sarkans, kaut kas neizdevās, un darbībā to nevar laist, kamēr tas nav salabots.","also":["kvalitātes pārbaudes","kvalitātes pārbaude"]},{"id":"deploy","g":"change","word":"Deploy","text":"Jaunas versijas padarīšana pieejamai, piemēram, serverī, kur to lieto cilvēki."},{"id":"release","g":"change","word":"Laidiens","text":"Nosaukta pabeigta darba paka, kas nonāk darbībā vienlaikus, ar īsām piezīmēm par to, kas mainījies. 🚀 Laidieni piezīmes uzraksta no izdarītajām kartītēm.","also":["laidieni","laidiena","laidienu","laidienā","laidienos","laidieniem"]},{"id":"rollback","g":"change","word":"Atgriešana","text":"Atgriešanās pie pēdējās versijas, kas strādāja, kad jaunā rada nepatikšanas. AI-gile no katras izmaiņas atcelšanas soļiem izveido kontrolsarakstu.","also":["atgriezt","atgriešanas","atgriešanu","atgrieza","atgriezts"]},{"id":"live","g":"change","word":"Darbībā","text":"Īstā versija, ko cilvēki lieto, pretstatā kopijai, kurā izmēģina lietas. Izstrādātāji to sauc arī par produkciju.","also":["produkcija","produkcijā","produkcijas"],"noTip":1},{"id":"change","g":"change","word":"Izmaiņa","text":"Plānota izmaiņa kaut kam, uz ko cilvēki paļaujas, iepriekš pierakstīta: kas, kāpēc, risks, kad un kā to atcelt. Sāc ar 🔀 Iesniegt izmaiņu.","also":["izmaiņas","izmaiņu","izmaiņām","izmaiņu pieprasījums","izmaiņu pieprasījumi"],"noTip":1},{"id":"risk","g":"change","word":"Risks","text":"Kaut kas, kas var noiet greizi, novērtēts pēc tā, cik tas ticams un cik slikti būtu. ⚠️ Riski tos glabā vienā sarakstā, augstākais vērtējums pirmais, katram ar datumu, kad paskatīties vēlreiz.","also":["riski","riska","risku","riskiem","risku reģistrs"]},{"id":"chgwin","g":"change","word":"Izmaiņu logs","text":"Laiki, kad izmaiņas drīkst nonākt darbībā, piemēram, mierīgs otrdienas vakars. Ārpus loga izmaiņu kartīti nevar pabeigt, ja vien tā nav ārkārtas izmaiņa.","also":["izmaiņu logi","izmaiņu loga","izmaiņu logā","izmaiņu logus"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Ātrs balsojums tieši pirms izmaiņa nonāk darbībā: katrs, kam jāapstiprina, saka Go vai No go. Tā notiek tikai tad, ja visi piekrīt.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Apstiprinājums","text":"Gaidīšana uz „jā”, pirms darbs sākas. Kartīte, ko iesniedz draugs, vai izmaiņa gaida ✅ Apstiprinājumos, līdz tu to apstiprini vai noraidi.","also":["apstiprinājumi","apstiprinājuma","apstiprinājumu","apstiprinājumiem"]},{"id":"quiettime","g":"change","word":"Klusais laiks","text":"Laika posms, piemēram, straume, demonstrācija vai nakts, kad nekas nenonāk darbībā. Komandas turpina strādāt un testēt, bet palaišana darbībā gaida, līdz tas beidzas. Citur to sauc par izmaiņu iesaldēšanu.","also":["klusie laiki","klusā laika","klusajā laikā","izmaiņu iesaldēšana"]},{"id":"service","g":"run","word":"Pakalpojums","text":"Kaut kas, ko tu uzbūvēji un uz ko cilvēki paļaujas, piemēram, tīmekļa vietne vai lietotne, un par ko rūpējas, lai tas turpinātu strādāt. Atzīmē „Šis projekts ir pakalpojums” un norādi, ko tas piedāvā, kas to lieto un kas dežurē.","also":["pakalpojumi","pakalpojuma","pakalpojumu","pakalpojumam","pakalpojumā","pakalpojumiem"]},{"id":"uptime","g":"run","word":"Pieejamības pārbaude","text":"Automātiska pārbaude ik pēc dažām minūtēm, vai tavs pakalpojums vēl atbild. Ja tā vairākas reizes pēc kārtas neizdodas, AI-gile pats atver incidenta kartīti.","also":["pieejamība","pieejamības pārbaudes","pieejamības pārbaudi","uptime"]},{"id":"statuspage","g":"run","word":"Statusa lapa","text":"Publiska lapa, kas rāda, vai pakalpojums strādā (zaļš, oranžs vai sarkans), ar jaunāko ziņu, lai cilvēki, kas to lieto, varētu paskatīties, nevis jautāt.","also":["statusa lapas","statusa lapā","statusa lapu"]},{"id":"desk","g":"run","word":"Pakalpojumu galds","text":"Vieta, kur ienāk jautājumi un ziņojumi no cilvēkiem, kas lieto tavu pakalpojumu. AI-gile katru sakārto kā pieprasījumu, incidentu vai ideju un pasaka, ja tas izskatās pēc kaut kā jau ziņota.","also":["pakalpojumu galdi","palīdzības dienests","atbalsta galds"]},{"id":"svcrequest","g":"run","word":"Pakalpojuma pieprasījums","text":"Kāds lūdz kaut ko ikdienišķu, piemēram, jaunu kontu vai nelielu palīdzību, nevis ziņo, ka kaut kas ir salūzis. Tas gaida savu kārtu; incidents iet pirmais.","also":["pakalpojumu pieprasījumi"]},{"id":"incident","g":"run","word":"Incidents","text":"Kaut kas, kas tieši tagad ir salūzis cilvēkiem, kas to lieto, piemēram, nedarbojas tīmekļa vietne. 🔥 Incidenta kartīte apsteidz rindu: vispirms to atkal jāiedarbina.","also":["incidenti","incidenta","incidentu","incidentam","incidentiem","incidentā"]},{"id":"major","g":"run","word":"Liels incidents","text":"Liels incidents: skarti daudzi cilvēki vai apdraudēta nauda vai dati. Viena poga liek visām komandām pie tā strādāt (spiets), pamodina dežurējošo un ik pēc 30 minūtēm prasa statusa ziņu.","also":["lieli incidenti","liela incidenta","lielu incidentu","lielā incidentā"]},{"id":"oncall","g":"run","word":"Dežūra","text":"Būt tam, kas atbild, kad kaut kas salūst, pat naktī. Katram pakalpojumam ir dežurējošs komandas dalībnieks, ko pamodina pirmo, kad notiek tā incidents.","also":["dežurē","dežurējošais","dežurējošo","dežūrā","dežūras","on-call"]},{"id":"replyby","g":"run","word":"Atbildes termiņš","text":"Cik ilgi kartīte drīkst gaidīt pirmo atbildi, piemēram, stundu incidentam. Pēc tam tā saņem sarkanu pulksteni, lai nekas netiktu klusi aizmirsts. To sauc arī par reakcijas mērķi.","also":["atbildes termiņi","atbildes termiņa","atbildes termiņu","reakcijas mērķis","reakcijas mērķi"]},{"id":"postmortem","g":"run","word":"Pēcanalīze","text":"Īss atskats pēc incidenta: kas notika, kas palīdzēja un ko mainīt, nevienu nevainojot. Incidentu nevar aizvērt bez tās.","also":["pēcanalīzes","pēcanalīzi","pēcanalīzē","post-mortem","postmortem","pēcincidenta pārskats"]},{"id":"problem","g":"run","word":"Problēma","text":"Apslēptais cēlonis vienam vai vairākiem incidentiem. 🧩 Problēmas kartīte sagrupē incidentus, kas atkārtojas, lai cēloni atrastu un salabotu uz visiem laikiem.","also":["problēmas","problēmu","problēmai","problēmām"],"noTip":1},{"id":"rootcause","g":"run","word":"Pamatcēlonis","text":"Īstais iemesls, kāpēc kaut kas salūza, nevis tikai tas, ko redzēji noejam greizi. Salabo pamatcēloni, un incidents vairs neatkārtojas.","also":["pamatcēloņi","pamatcēloņa","pamatcēloni","pamatcēloņus"]},{"id":"workaround","g":"run","word":"Apiešanas risinājums","text":"Veids, kā uzturēt lietas darbībā, līdz īstais labojums ir gatavs, piemēram, kaut ko restartēt, kad tas iestrēgst. To pieraksta problēmas kartītē, lai nevienam tas nav jāizdomā no jauna.","also":["apiešanas risinājumi","apiešanas risinājuma","apiešanas risinājumu","pagaidu risinājums"]},{"id":"knownerror","g":"run","word":"Zināmā kļūda","text":"Problēma, kuras cēlonis ir saprasts un kurai ir apiešanas risinājums, bet kas vēl nav salabota. 🧩 Zināmās kļūdas tās uzskaita, lai visi lietotu apiešanas risinājumu, nevis raktu no jauna.","also":["zināmās kļūdas","zināmo kļūdu","zināma kļūda","zināmām kļūdām"]},{"id":"runbook","g":"run","word":"Runbook","text":"Soli pa solim instrukcija, kā salabot zināma veida nepatikšanas, lai tas katru reizi tiktu izdarīts vienādi un ātri. Pēc liela incidenta komanda var to ierosināt, un tu dod savu OK.","also":["runbooks","runbook"]},{"id":"ci","g":"run","word":"Konfigurācijas vienība","text":"Viena lieta, no kuras atkarīgs tavs pakalpojums, piemēram, serveris, domēns, sertifikāts, atslēga vai piegādātājs. 🗂️ Konfigurācijas vienības tās uzskaita katram pakalpojumam, lai redzētu, ko incidents ietekmē un kam vajag atjaunošanu vai dublējumu.","also":["konfigurācijas vienības"]},{"id":"expiry","g":"run","word":"Derīguma termiņš","text":"AI-gile pieskata datumus, piemēram, kad beidzas sertifikāts vai domēns. 30 dienas pirms datuma tas izveido vienu kartīti, lai to atjaunotu, un nekas pēkšņi nepārstāj darboties.","also":["derīguma termiņi","termiņš","termiņu uzraudzība"]},{"id":"backup","g":"run","word":"Dublējums","text":"Saglabāta tavu datu kopija no agrāka laika, uz ko paļauties, ja kaut kas pazūd vai sabojājas. AI-gile katru dienu izveido tavu dēļu dublējumu.","also":["dublējumi","dublējuma","dublējumu","dublējumā","dublējumiem","rezerves kopija"]},{"id":"restore","g":"run","word":"Atjaunošana","text":"Datu atlikšana atpakaļ no dublējuma. Dublējums patiesi skaitās tikai tad, kad zini, ka to var atjaunot, tāpēc ik pa laikam vērts pamēģināt.","also":["atjaunot","atjaunots","atjaunoti","atjaunošanu"]},{"id":"svcreview","g":"run","word":"Pakalpojuma pārskats","text":"Atskats uz viena pakalpojuma mēnesi: atvērtie un salabotie incidenti, cik ātri cilvēki saņēma atbildi, pieejamība un izlietotie tokeni. Ikmēneša pārskats to rāda katram pakalpojumam.","also":["pakalpojumu pārskati","ikmēneša pārskats","ikmēneša pārskati"]},{"id":"accessreview","g":"run","word":"Piekļuves pārskats","text":"Ik pēc 90 dienām pārbauda, kas joprojām var tikt iekšā: kopīgošanas saites, draugu lomas un glabātie noslēpumi. Katru tu patur vai noņem, lai veca piekļuve nepaliktu karājamies.","also":["piekļuves pārskati"]},{"id":"improvements","g":"run","word":"Uzlabojumu saraksts","text":"Viss, ko komanda nolēma uzlabot, vienuviet: retro ieteikumi, pārskatu darbības un problēmu labojumi, katram ar savu statusu. Atrodams sadaļā 📈 Uzlabojumi.","also":["uzlabojumu saraksti","uzlabojumi"]},{"id":"tokencap","g":"run","word":"Tokenu limits","text":"Ikmēneša limits tokeniem, ko pakalpojuma aģenti drīkst izmantot. Pie 80% tu saņem brīdinājumu; pie 100% to fona darbs gaida līdz nākamajam mēnesim vai līdz tu paaugstini limitu.","also":["tokenu limiti"]},{"id":"backlog","g":"team","word":"Backlogs","text":"Idejas un darbs, kas vēl nav ieplānots. Nekas no tā netiek darīts, kamēr tas nepāriet uz Darāmais."},{"id":"sprint","g":"team","word":"Sprints","text":"Īss darba posms (bieži nedēļa vai divas) ar saskaņotu kartīšu kopu, kas jāpabeidz.","also":["sprinti","sprinta","sprintu","sprintam","sprintiem","sprintā","sprintos"]},{"id":"standup","g":"team","word":"Stand-up","text":"Īsa ikdienas sapulce: ko katrs komandas dalībnieks izdarīja, ko darīs tālāk un kas kavē darbu.","also":["standup","stand-upi","stand-upa","stand-upu"]},{"id":"kanban","g":"team","word":"Kanban","text":"Dēlis ar kolonnām (Darāmais, Procesā, Izdarīts), kurā kartītes darba gaitā pārvietojas no kreisās uz labo."},{"id":"wip","g":"team","word":"WIP limits","text":"Procesā esošais darbs: cik kartīšu kolonnā drīkst būt visvairāk, lai komanda lietas pabeidz, pirms sāk jaunas.","also":["WIP"]},{"id":"dod","g":"team","word":"Pabeigts definīcija","text":"Komandas īss kontrolsaraksts, ko nozīmē „pabeigts”, piemēram, notestēts un paskaidrots, pirms kartīte tiek nodota tev. Tās dvīne, Gatavs sākšanai definīcija, nosaka, kad kartīte ir pietiekami skaidra, lai sāktu.","also":["Gatavs sākšanai definīcija","Definition of Done","Definition of Ready"]},{"id":"testpile","g":"team","word":"Testu kaudze","text":"Pabeigtās kartītes, kas gaida, lai tu tās izmēģinātu, cita pēc citas. Pieņem vienu vai sūti to atpakaļ ar piezīmi, un parādās nākamā.","also":["testu kaudzes","testu kaudzi","testu kaudzē"]},{"id":"retro","g":"team","word":"Retro","text":"Atskats uz to, kā komanda strādā, lai vienotos par vienu lietu, ko darīt labāk. AI-gile retro ierosina izmaiņu komandas darba kārtībā, un tu saki Go vai Vēl ne.","also":["retrospektīva","retrospektīvas","retrospektīvu"]},{"id":"peerreview","g":"team","word":"Kolēģu pārskats","text":"Otrs acu pāris: cits MI pārbauda katras kartītes darbu, pirms tā nonāk pie tevis, tāpēc cauri izslīd mazāk kļūdu.","also":["kolēģu pārskata","kolēģu pārskatu","koda pārskats"]},{"id":"swarm","g":"team","word":"Spiets","text":"Visi uz klāja: katra komanda atliek citu darbu, lai palīdzētu vienā steidzamā projektā, līdz tas ir sakārtots. Citi projekti tikmēr gaida.","also":["spietā","spietu","spieta"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Tas, kurš uztur darba plūsmu: pamana iestrēgušas kartītes, pamudina komandas un atgādina tev, kas gaida. AI-gile to visos projektos dara Lead Scrum Master.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Aģents","text":"MI, kas pie uzdevuma strādā patstāvīgi: lasa kodu, veic izmaiņas, palaiž pārbaudes un ziņo atpakaļ.","also":["aģenti","aģenta","aģentu","aģentiem","agent","agents"]},{"id":"token","g":"team","word":"Tokens","text":"Vienība, kurā skaita MI lietojumu: apmēram daži teksta burti, kas izlasīti vai uzrakstīti. Jo mazāk tokenu, jo vairāk plāna atlicis.","also":["tokeni","tokena","tokenu","tokeniem","token","tokens"]},{"id":"hook","g":"team","word":"Āķis","text":"Neliela komanda, kas pati darbojas noteiktā brīdī, piemēram, kad sākas MI sesija, lai komanda dzirdētu tavus komentārus.","also":["hook","hooks","āķi","āķa","āķu"]}]}};
